export async function coordinationIntegrity(pool:pg.Pool,f:CoordinationFixture,directory:string){
  const results:string[]=[],version=(await pool.query("select v.* from world_map_connection_head h join world_map_connection_version v on v.id=h.version_id where h.timeline_id=$1 and h.connection_id=$2",[f.primary,f.connection100])).rows[0];
  async function rejects(name:string,run:(client:pg.PoolClient)=>Promise<unknown>){const client=await pool.connect();try{await client.query("BEGIN");await assert.rejects(run(client));results.push(name);console.log(`PASS DB ${name}`);}finally{await client.query("ROLLBACK");client.release();}}
  async function insert(client:pg.PoolClient,patch:Record<string,unknown>){const row={...version,id:id(),previous_version_id:version.id,...patch},keys=Object.keys(row);assert.ok(keys.every(k=>/^[a-z_]+$/.test(k)));return client.query(`insert into world_map_connection_version (${keys.map(k=>`"${k}"`).join(",")}) values (${keys.map((_,i)=>`$${i+1}`).join(",")})`,keys.map(k=>row[k]));}
  await rejects("immutable source content and attribution",client=>client.query("update world_map_connection_version set author_id='other-god' where id=$1",[version.id]));
  await rejects("World owner authorship",client=>insert(client,{author_id:"other-god"}));
  await rejects("exact preceding head required",client=>insert(client,{previous_version_id:f.earlyVersion}));
  await rejects("forged shared baseline snapshot rejected",client=>insert(client,{source:{...version.source,baseline:{...version.source.baseline,revision:999}}}));
  await rejects("payload periods agree with indexed periods",client=>insert(client,{draft:{...version.draft,startYear:999}}));
  await rejects("source labels cannot be forged",client=>insert(client,{source:{...version.source,destinationName:"Forged destination"}}));
  await rejects("head cannot skip optimistic revision",client=>client.query("update world_map_connection_head set revision=revision+2 where timeline_id=$1 and connection_id=$2",[f.primary,f.connection100]));
  await rejects("unadopted or stale parent cannot be retained",client=>client.query("insert into world_map_connection_head (timeline_id,world_id,map_id,geography_id,connection_id,version_id,revision,mode) values($1,$2,$3,$4,$5,$6,1,'retained')",[f.sibling,f.worldId,f.mapId,f.town,f.connection300,version.id]));
  for(const patch of [{account:null},{status:null},{accountYear:1.5},{protected:null},{endYear:99},{destinationMapId:null}])assert.equal((await pool.query("select world_map_connection_payload_valid($1::jsonb,$2::jsonb) valid",[{...version.draft,...patch},version.source])).rows[0].valid,false);
  results.push("strict JSON null, enum, integer year and destination validation");
  assert.deepEqual((await pool.query("select * from world_map_connection_version where id=$1",[version.id])).rows[0],version);
  await writeFile(`${directory}/integrity-results.json`,JSON.stringify({passed:results.length,results,allRejectedTransactionsRolledBack:true},null,2));
}

